def transform(grid):
    # Fill the interiors of outlined motifs with the common target color 7;
    # the 4x4 hollow square is the contrasting 2-colored motif.
    g=[r[:] for r in grid]
    R,C=len(g),len(g[0])
    # Identify monochromatic rectangular frames, fill enclosed area by size/color.
    for r in range(R-1):
      for c in range(C-1):
        col=g[r][c]
        if col==6 or col==0: continue
        # find rectangular boundary of this color from top-left
        for r2 in range(r+2,R):
          for c2 in range(c+2,C):
            if all(g[r][x]==col for x in range(c,c2+1)) and all(g[r2][x]==col for x in range(c,c2+1)) and all(g[y][c]==col and g[y][c2]==col for y in range(r,r2+1)):
              # only interior cells that are background
              fill=7
              for y in range(r+1,r2):
                for x in range(c+1,c2):
                  if g[y][x] != col: g[y][x]=fill
              break
    # fill enclosed single-cell holes in 3x3 objects (including 0/8/5)
    for r in range(1,R-1):
      for c in range(1,C-1):
        if g[r][c] not in (0,3,6): continue
        # neighbors same color around center, ring color
        for col in set(g[r+dy][c+dx] for dy,dx in [(-1,0),(1,0),(0,-1),(0,1)]):
          if col not in (0,8,5): continue
          if all(g[r+dy][c+dx]==col for dy,dx in [(-1,0),(1,0),(0,-1),(0,1)]): g[r][c]=7
    return g
